import{_ as i,o as a,c as t,ag as l}from"./chunks/framework.1IVNT0ce.js";const p=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/architecture.md","filePath":"concepts/architecture.md"}'),r={name:"concepts/architecture.md"};function o(s,e,n,d,h,c){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Klix is organized around a small set of cooperating subsystems. The implementation is intentionally compact, so understanding the architecture is mostly about understanding the runtime flow.</p><p>See also:</p><ul><li><a href="./app">App</a></li><li><a href="./session">Session</a></li><li><a href="./router">Router</a></li><li><a href="./input-engine">Input Engine</a></li><li><a href="./renderer">Renderer</a></li><li><a href="./layout">Layout</a></li><li><a href="./ui">UI Namespace</a></li></ul><h2 id="the-runtime-shape" tabindex="-1">The Runtime Shape <a class="header-anchor" href="#the-runtime-shape" aria-label="Permalink to &quot;The Runtime Shape&quot;">​</a></h2><p>At runtime, a typical Klix app looks like this:</p><ol><li><code>App</code> is created and registrations happen</li><li><code>app.run()</code> parses top-level CLI flags</li><li>Klix creates a <code>Session</code></li><li>Klix chooses a renderer and input engine</li><li>Klix emits the <code>start</code> event</li><li>Klix reads a line</li><li>Klix emits the <code>input</code> event</li><li>Klix parses the line through the router</li><li>Klix runs middleware</li><li>Klix invokes the command handler</li><li>Klix emits <code>exit</code> and saves state on shutdown</li></ol><p>That flow is implemented in <code>klix/app.py</code>. See <a href="./app">App</a>.</p><h2 id="subsystems" tabindex="-1">Subsystems <a class="header-anchor" href="#subsystems" aria-label="Permalink to &quot;Subsystems&quot;">​</a></h2><h3 id="app" tabindex="-1">App <a class="header-anchor" href="#app" aria-label="Permalink to &quot;App&quot;">​</a></h3><p><code>App</code> is the composition root. It owns:</p><ul><li>command registry</li><li>middleware list</li><li>event bus</li><li>router</li><li>state manager</li><li>completer registration</li><li>the main run loop</li></ul><h3 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h3><p><code>Session</code> is the per-terminal runtime object passed into handlers. It contains:</p><ul><li>typed app state</li><li>metadata about the terminal</li><li>input history</li><li>UI access through <code>session.ui</code></li><li>a background task registry</li></ul><h3 id="router" tabindex="-1">Router <a class="header-anchor" href="#router" aria-label="Permalink to &quot;Router&quot;">​</a></h3><p>The router is responsible for:</p><ul><li>mapping a raw slash-command line to <code>ParsedCommand</code></li><li>resolving aliases</li><li>validating arguments against <code>args_schema</code></li></ul><p>The parser is intentionally simple. It is not a full shell parser. See <a href="./router">Router</a>.</p><h3 id="event-bus" tabindex="-1">Event Bus <a class="header-anchor" href="#event-bus" aria-label="Permalink to &quot;Event Bus&quot;">​</a></h3><p>The event bus is a small ordered dispatcher. It supports both sync and async handlers and is used for lifecycle and input-related hooks.</p><h3 id="middleware" tabindex="-1">Middleware <a class="header-anchor" href="#middleware" aria-label="Permalink to &quot;Middleware&quot;">​</a></h3><p>Middleware wraps command dispatch. It runs after parsing and before the final handler. That means middleware can inspect <code>ctx.command</code>.</p><h3 id="input-engine" tabindex="-1">Input Engine <a class="header-anchor" href="#input-engine" aria-label="Permalink to &quot;Input Engine&quot;">​</a></h3><p>The input engine is the thin prompt layer over <code>prompt_toolkit</code>. It owns:</p><ul><li>input mode</li><li>prompt history</li><li>key bindings</li><li>CI fallback behavior</li></ul><h3 id="ui-namespace" tabindex="-1">UI Namespace <a class="header-anchor" href="#ui-namespace" aria-label="Permalink to &quot;UI Namespace&quot;">​</a></h3><p><code>session.ui</code> is the developer-facing convenience surface. It binds together:</p><ul><li>renderer-backed print/stream helpers</li><li><code>session.ui.input</code></li><li><code>session.ui.output</code></li><li><code>session.ui.layout</code></li><li>cursor helpers</li></ul><h2 id="why-the-architecture-looks-like-this" tabindex="-1">Why The Architecture Looks Like This <a class="header-anchor" href="#why-the-architecture-looks-like-this" aria-label="Permalink to &quot;Why The Architecture Looks Like This&quot;">​</a></h2><p>Klix is trying to be a framework, not a single-purpose tool. That pushes the architecture toward separation:</p><ul><li>routing is separate from input reading</li><li>middleware is separate from command logic</li><li>session state is separate from app registration</li><li>rendering is separate from UI widgets</li></ul><p>This is what lets the same framework support:</p><ul><li>generated starter CLIs</li><li>command-driven demos like <a href="./../examples/minimal"><code>examples/minimal.py</code></a></li><li>more custom flows like the Gemini-style chat demo in <a href="./../examples/gemini-style-cli"><code>examples/chat_ai.py</code></a></li></ul><h2 id="current-implementation-boundaries" tabindex="-1">Current Implementation Boundaries <a class="header-anchor" href="#current-implementation-boundaries" aria-label="Permalink to &quot;Current Implementation Boundaries&quot;">​</a></h2><p>The docs in this folder reflect the current code, which includes some intentional simplifications:</p><ul><li>the layout system redraws coarsely instead of maintaining a fully persistent screen model</li><li>the event system exists for many event names, but only some events are actively emitted by <code>App.run()</code></li><li>command parsing is token-based, not shell-quote aware</li><li>persistence is file-based JSON with a simple version field</li></ul><p>These are not hidden footnotes. They affect how you should build with Klix today. Read:</p><ul><li><a href="./layout">Layout</a></li><li><a href="./events">Events</a></li><li><a href="./../guides/persistence">Persistence</a></li><li><a href="./../faq">FAQ</a></li></ul><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><h3 id="treating-klix-like-a-full-screen-tui-framework" tabindex="-1">Treating Klix like a full-screen TUI framework <a class="header-anchor" href="#treating-klix-like-a-full-screen-tui-framework" aria-label="Permalink to &quot;Treating Klix like a full-screen TUI framework&quot;">​</a></h3><p>Klix has layout regions, but the current implementation is still closer to a smart command-line runtime than a fully managed alternate-screen UI.</p><h3 id="expecting-middleware-for-plain-text-in-custom-loops-automatically" tabindex="-1">Expecting middleware for plain text in custom loops automatically <a class="header-anchor" href="#expecting-middleware-for-plain-text-in-custom-loops-automatically" aria-label="Permalink to &quot;Expecting middleware for plain text in custom loops automatically&quot;">​</a></h3><p>If you build a custom interaction loop outside <code>App.run()</code>, you need to explicitly route command lines through the router and middleware if you want that behavior.</p><h3 id="ignoring-the-simple-parser" tabindex="-1">Ignoring the simple parser <a class="header-anchor" href="#ignoring-the-simple-parser" aria-label="Permalink to &quot;Ignoring the simple parser&quot;">​</a></h3><p>If your command syntax needs shell-level quoting rules, nested subcommands, or highly flexible parsing, you should design around the current parser limits or extend the routing approach deliberately.</p>',46)])])}const m=i(r,[["render",o]]);export{p as __pageData,m as default};
